ALTER TYPE "OrganizationSequenceType" ADD VALUE 'SUBSCRIPTION';
CREATE TYPE "SubscriptionStatus" AS ENUM ('DRAFT','CONFIRMED','ACTIVE','PAUSED','CANCELLED','EXPIRED','CLOSED');
CREATE TYPE "SubscriptionAmendmentType" AS ENUM ('PAUSED','RESUMED','CANCELLED');
CREATE TABLE "subscriptions" ("id" UUID NOT NULL,"organization_id" UUID NOT NULL,"subscription_number" VARCHAR(64) NOT NULL,"customer_id" UUID NOT NULL,"plan_id" UUID NOT NULL,"status" "SubscriptionStatus" NOT NULL DEFAULT 'DRAFT',"start_date" DATE NOT NULL,"expiration_date" DATE,"billing_start_date" DATE NOT NULL,"currency_code" CHAR(3) NOT NULL,"payment_terms" VARCHAR(100),"auto_renew" BOOLEAN NOT NULL DEFAULT true,"current_period_start" DATE,"current_period_end" DATE,"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ(6) NOT NULL,CONSTRAINT "subscriptions_pkey" PRIMARY KEY ("id"));
CREATE TABLE "subscription_items" ("id" UUID NOT NULL,"subscription_id" UUID NOT NULL,"product_id" UUID,"variant_id" UUID,"description_snapshot" VARCHAR(2000) NOT NULL,"quantity" INTEGER NOT NULL,"unit_price" DECIMAL(19,4) NOT NULL,"currency_code" CHAR(3) NOT NULL,"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "subscription_items_pkey" PRIMARY KEY ("id"),CONSTRAINT "subscription_items_quantity_check" CHECK ("quantity">0));
CREATE TABLE "subscription_events" ("id" UUID NOT NULL,"organization_id" UUID NOT NULL,"subscription_id" UUID NOT NULL,"event_type" VARCHAR(64) NOT NULL,"occurred_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"actor_user_id" UUID,"metadata" JSONB,CONSTRAINT "subscription_events_pkey" PRIMARY KEY ("id"));
CREATE TABLE "subscription_amendments" ("id" UUID NOT NULL,"subscription_id" UUID NOT NULL,"amendment_type" "SubscriptionAmendmentType" NOT NULL,"effective_at" TIMESTAMPTZ(6) NOT NULL,"reason" VARCHAR(500),"before_snapshot" JSONB NOT NULL,"after_snapshot" JSONB NOT NULL,"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "subscription_amendments_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "subscriptions_organization_id_subscription_number_key" ON "subscriptions"("organization_id","subscription_number");
CREATE UNIQUE INDEX "subscriptions_organization_id_id_key" ON "subscriptions"("organization_id","id");
CREATE INDEX "subscriptions_organization_id_status_created_at_idx" ON "subscriptions"("organization_id","status","created_at");
CREATE INDEX "subscription_items_subscription_id_idx" ON "subscription_items"("subscription_id");
CREATE INDEX "subscription_events_organization_id_subscription_id_occurred_at_idx" ON "subscription_events"("organization_id","subscription_id","occurred_at");
CREATE INDEX "subscription_amendments_subscription_id_effective_at_idx" ON "subscription_amendments"("subscription_id","effective_at");
ALTER TABLE "subscriptions" ADD CONSTRAINT "subscriptions_customer_fkey" FOREIGN KEY ("organization_id","customer_id") REFERENCES "customers"("organization_id","id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "subscriptions" ADD CONSTRAINT "subscriptions_organization_id_fkey" FOREIGN KEY ("organization_id") REFERENCES "organizations"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "subscriptions" ADD CONSTRAINT "subscriptions_plan_fkey" FOREIGN KEY ("organization_id","plan_id") REFERENCES "plans"("organization_id","id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "subscription_items" ADD CONSTRAINT "subscription_items_subscription_fkey" FOREIGN KEY ("subscription_id") REFERENCES "subscriptions"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "subscription_events" ADD CONSTRAINT "subscription_events_subscription_fkey" FOREIGN KEY ("subscription_id") REFERENCES "subscriptions"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "subscription_amendments" ADD CONSTRAINT "subscription_amendments_subscription_fkey" FOREIGN KEY ("subscription_id") REFERENCES "subscriptions"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
